INSERT INTO `tipsters` (`id`, `user_id`, `slug`, `display_name`, `tagline`, `bio`, `country`, `specialties`, `avatar_url`, `payout_method`, `payout_details`, `status`, `commission_percent`, `admin_note`, `rating_avg`, `rating_count`, `created_at`, `approved_at`, `is_contributor`, `trial_days`, `guarantee`, `accepts_managed`, `managed_note`, `fee_paid_at`) VALUES
(1, 3, 'cracking', 'CHICKY', 'Football specialist', 'Sports betting tipsters are individuals or services that analyze statistics, team form, injuries, and historical data to provide expert predictions and recommendations for upcoming sports events. While they can save you hours of research time and offer expert insights into niche markets, finding a legitimate advisor requires extreme caution. Tipsters generally operate under two models: free tipsters, who share advice on social media or blogs to build an audience, and paid premium tipsters, who charge a monthly subscription fee for exclusive selections. While a skilled tipster can help disciplined bettors find value and implement better bankroll management, the industry is unfortunately filled with scams. To protect your funds, you must avoid major red flags, such as任何人 promising \"guaranteed wins\" or \"fixed matches,\" as no one can predict sports with 100% certainty. Shady services also frequently delete losing posts or refuse to publish a transparent, long-term track record. When choosing a tipster, look for a verified history spanning hundreds of bets with a realistic Return on Investment (ROI) between 5% and 15%. Ultimately, you should always test a new tipster\'s advice by paper-trading or using tiny stakes before risking significant capital on their recommendations.', 'Kenya', '', 'media.php?id=4', 'paypal', 'balaammaina@gmail.com', 'active', 30, NULL, 0.00, 0, '2026-10-14 06:45:35', '2026-10-14 06:47:17', 1, 1, 1, 1, NULL, NULL),
(2, 4, 'blackcard', 'Blackcard', 'Football specialist', 'Pundit with an excellent track record.', 'Kenya', 'btts,ov/un', NULL, 'paypal', '0726696262', 'active', NULL, NULL, 0.00, 0, '2026-10-18 01:35:51', '2026-10-18 01:39:22', 0, 0, 0, 0, NULL, NULL),
(3, 5, 'khalifa', 'Khalifa', 'Bundesliga specialist', 'Am the best that has ever been and will ever be.', 'Kenya', 'btts,ov/un', NULL, 'mpesa', 'onan8929@gmail.com', 'active', NULL, NULL, 0.00, 0, '2026-10-18 03:10:16', '2026-10-18 03:27:19', 0, 0, 0, 0, NULL, NULL);
